@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, edited_by, stated, stated_due, stated_late, corrects, due_by, terms, deferred_until, proofs, proof_photos, split_from, late_entry, reminded_on, ext_ref, tags, void_reason, settle_batch, review_on, waived, held, review_user,"
            + " (SELECT c.claim_date FROM claim c WHERE c.sheet_id = claim.sheet_id AND c.person_id = claim.person_id"
            + " AND c.claim_number = claim.corrects) AS corrected_date,"
            + " CASE WHEN locked_on = (SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id) THEN locked_by END AS locked_by_now";

    private static final RowMapper<Claim> ROW = (rs, n) -> {
        java.sql.Date reminded = rs.getDate("reminded_on");
        claim.setRemindedOn(reminded == null ? null : reminded.toLocalDate());
        claim.setWaived(rs.getBoolean("waived"));
        claim.setHeld(rs.getBoolean("held"));
        claim.setReviewUser(rs.getString("review_user"));
        java.sql.Date review = rs.getDate("review_on");
        claim.setReviewOn(review == null ? null : review.toLocalDate());
        claim.setRef(rs.getString("ext_ref"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        claim.setSettleBatch((Integer) rs.getObject("settle_batch", Integer.class));
        claim.setLockedBy(rs.getString("locked_by_now"));
        then.dueBy = dueBy;
        then.terms = terms;
        then.deferredUntil = deferredUntil;
        then.proofs = proofs;
        then.proofPhotos = proofPhotos;
        then.splitFrom = splitFrom;
        then.lateEntry = lateEntry;
        then.remindedOn = remindedOn;
        then.waived = waived;
        then.held = held;
        then.reviewUser = reviewUser;
        then.reviewOn = reviewOn;
        then.ref = ref;
        then.tags = tags;
        then.voidReason = voidReason;
        then.settleBatch = settleBatch;
 */
public record ClaimResponse(String id, String personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated,
        String statedDue, String corrects, String roundDate, String dueBy, List<String> log, String deferredUntil,
        int proofs, String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref,
        List<String> tags, String voidReason, List<String> comments, String batch, List<String> lines, String reviewOn, boolean waived,
        String statedLate, int proofReceipts, int proofPhotos, boolean held, List<Shared> shares,
        String reviewUser) {

    /** A share of the claim as the screen reads it: the holder's person id and their percent, two decimals. */
    public record Shared(String personId, String share) {
                claim.getRef() == null ? "" : claim.getRef(),
                claim.tagList(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
                comments,
                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()),
                lines,
                claim.getReviewOn() == null ? "" : claim.getReviewOn().toString(),
                claim.isWaived(),
                claim.getStatedLate() == null ? "" : claim.getStatedLate().toPlainString(),
                claim.getProofReceipts(), claim.getProofPhotos(), claim.isHeld(),
                shares.stream().map((s) -> new Shared(String.valueOf(s.personId()), s.share().toPlainString())).toList(),
                claim.getReviewUser() == null ? "" : claim.getReviewUser());
    }
}

