content.content:
  comments: string[];
  /** The number of the bulk settle batch that settled it; '' when none did (settled one at a time, or not settled). */
  batch: string;
  /** Its lines, oldest first, as `<label> <qty> x <unit>`; while it has any, its amount is their total. */
  lines: string[];
  /** The sheet's today (yyyy-MM-dd) when it went to REVIEW; '' when it never did. */
  reviewOn: string;
  /**
   * Its shares with other people on the sheet, oldest first: each holder's person id and their percent
   * (two decimals). A holder's part of its due is the due times their share divided by 100, rounded half
   * to even; its own person keeps the rest.
   */
  shares: ClaimShare[];
  /** The user a steward assigned it to review while in REVIEW; '' when none. Kept once it leaves REVIEW. */
  reviewUser: string;
};

/** A holder's share of a claim: their person id and their percent, two decimals. */
export type ClaimShare = { personId: string; share: string };

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim is late for review: it is in REVIEW and its review day plus the review SLA in days
 * ('' for none: never late) is before the sheet's today.
 */
export function isReviewLate(c: Claim, today: string, reviewSla: string): boolean {
  if (c.status !== 'REVIEW' || c.reviewOn === '' || reviewSla === '' || today === '') return false;
  const [y, m, d] = c.reviewOn.split('-').map(Number);
  const due = new Date(Date.UTC(y, m - 1, d + Number(reviewSla))).toISOString().slice(0, 10);
  return due < today;
}

/**
  /** The rounding mode, half-up or half-even ('' for none: by the policy date), dated: a claim rounds by the one in force on its date. */
  rounding: string;
  /** The due above which a claim, on its date, goes to REVIEW instead of OPEN when it is opened ('' for none), dated. */
  reviewThreshold: string;
  /** The escalation gap in days ('' for off), not dated: a reminder at least that many days after the claim's previous one escalates it, once. */
  escalateAfter: string;
  /** The review SLA in days ('' for none), not dated: a REVIEW claim whose review day plus it is before the sheet's today is late. */
  reviewSla: string;
  /** The proof kinds, a comma separated list of kinds, receipt or photo ('' for none), not dated: while set, a claim above the proof threshold needs a proof of each. */
  proofKinds: string;
  /** The default grade, one of the grades ('' for A), not dated: the grade a quick-added person and an imported line with a blank grade take. */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The sheet's review SLA in days ('' for none, until the settings are read). */
export function useReviewSla(sheetId: string): string {
  return useSettings(sheetId).data?.reviewSla ?? '';
}

